{
  "implementation": "import math

def solve(case):
    matrix = case.get('matrix')
    if not matrix or not isinstance(matrix, list) or len(matrix) == 0:
        raise ValueError('Matrix is empty or invalid')
    rows = len(matrix)
    cols = len(matrix[0])
    for row in matrix:
        if not isinstance(row, list) or len(row) != cols:
            raise ValueError('Matrix rows must have same length')
    idf = []
    for j in range(cols):
        df = 0
        for i in range(rows):
            if matrix[i][j] != 0:
                df += 1
        idf_val = math.log(1 + rows / (1 + df))
        idf.append(idf_val)
    weighted_matrix = []
    row_degree = []
    for i in range(rows):
        weighted_row = []
        sum_row = 0.0
        for j in range(cols):
            val = matrix[i][j] * idf[j]
            weighted_row.append(val)
            sum_row += val
        weighted_matrix.append(weighted_row)
        row_degree.append(sum_row)
    idf_rounded = [round(x, 6) for x in idf]
    row_degree_rounded = [round(x, 6) for x in row_degree]
    weighted_matrix_rounded = [[round(x, 6) for x in row] for row in weighted_matrix]
    return {
        'idf': idf_rounded,
        'row_degree': row_degree_rounded,
        'weighted_matrix': weighted_matrix_rounded
    }"
}
